"""Migrated Meridian CRM 4.2 ACCT_MASTER validation rules."""

from decimal import Decimal
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    if row is None:
        return ""
    return row.get(column, "")


def _length(value: Any) -> int:
    if value is None:
        return 0
    return len(str(value))


def _numeric(value: Any) -> Decimal:
    """Apply legacy numeric-context coercion for empty values."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _nvl(value: Any, default: Any) -> Any:
    return default if value is None or value == "" else value


def _failure(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {"code": code, "message": message, "severity": severity}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an ACCT_MASTER post-write image in legacy rule-file order."""
    del today  # Present for the fixed interface; unused by these rules.

    errors: list[dict] = []
    old_record = old if event == "UPDATE" else None

    # ACC-001: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if _length(_value(record, "ACCT_NM")) < 2:
            errors.append(_failure("E1001", "Account name too short"))

    # ACC-002: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        account_type = _value(record, "ACCT_TYP")
        if not (
            account_type == "C"
            or account_type == "P"
            or account_type == "R"
            or account_type == "X"
        ):
            errors.append(_failure("E1002", "Invalid account type"))

    # ACC-003: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        annual_revenue = _numeric(_nvl(_value(record, "ANN_REV"), 0))
        if annual_revenue < 0:
            errors.append(_failure("E1003", "Annual revenue negative"))

    # ACC-004: UPDATE
    if event == "UPDATE":
        if (
            _value(old_record, "CRED_HOLD") == "Y"
            and _value(record, "CRED_HOLD") == "N"
            and _numeric(_value(record, "CRED_LIMIT")) <= 0
        ):
            errors.append(
                _failure(
                    "E1004",
                    "Cannot release credit hold with zero credit limit",
                )
            )

    # ACC-005: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if _length(_value(record, "REGION_CD")) != 3:
            errors.append(
                _failure(
                    "E1005",
                    "Region code must be 3 chars",
                    "WARN",
                )
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
